INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "徐达", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "濠州人，1353年随朱元璋南略。", "biography": null, "status": "draft", "id": "0f28446e-78b0-5db1-9677-98777005803e"}, {"name": "李文忠", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱元璋姊子，1354年归舅获赐朱姓。", "biography": null, "status": "draft", "id": "937816d2-8a96-5b84-9cae-f26cdcacfa7b"}, {"name": "冯国胜", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴将，参与伏击陈友谅及追击战。", "biography": null, "status": "draft", "id": "11681f87-f6f7-58db-93b2-dad66d159d27"}, {"name": "邓愈", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年从朱元璋设伏擒陈埜先。", "biography": null, "status": "draft", "id": "5fbf3347-c8f3-5eaa-aa83-d0681e64b192"}, {"name": "汤和", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年夺桥取和阳，后从朱渡江。", "biography": null, "status": "draft", "id": "76a3c1b3-e175-593d-99d7-63da30cef072"}, {"status": "draft", "name": "郭子兴", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "定远人，1352年聚壮士称元帅据濠州，留用朱元璋，后将马公托孤养女嫁之。", "biography": null, "id": "1496aa3f-23c8-51d2-bbe6-07e3bfda07bd"}, {"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"name": "库库特穆尔（察罕特穆尔养子）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "本姓王名保保，察罕外甥，养为子；继掌其军。", "biography": null, "status": "draft", "id": "c00ceaa1-c47d-5d7f-bbe7-4c2ba9cfe8df"}, {"name": "傅友德", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "原陈友谅小孤山守将，1361年降吴。", "biography": null, "status": "draft", "id": "052c6ab9-234a-5d89-9bad-ec31f6774b50"}, {"name": "杨宪（朱元璋儒士）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1356年朱元璋录用的儒士，奉使张士诚而被扣留；与旧南宋使金副使杨宪分开。", "biography": null, "status": "draft", "id": "0b8375cf-8092-5291-8774-008709bac291"}, {"name": "周德兴", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "吴后明左丞，1367年奉命取广西，1368年取全州。", "biography": null, "status": "draft", "id": "b38e5f86-1f46-53af-90e5-784532a2661c"}, {"name": "李善长", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "1353年受朱元璋留为幕书记。", "biography": null, "status": "draft", "id": "fcb986aa-d440-5732-984a-f4c744f5a06d"}, {"name": "汪广洋", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年任朱元璋帅府令史。", "biography": null, "status": "draft", "id": "ac800e6b-ef48-5dc3-964b-d67d64245b02"}, {"name": "刘基", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "青田人，反对招抚方国珍被谪，曾任儒学副提举。", "biography": null, "status": "draft", "id": "bb5b8872-dbd3-576b-b02d-3b844e5a38e7"}, {"name": "廖永忠", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴水军将，1361年破安庆水寨。", "biography": null, "status": "draft", "id": "ccd9ff8d-290a-5c16-b1c7-90eeb0f8d3ee"}, {"name": "升（明玉珍子）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "明玉珍之子，1362年立太子。", "biography": null, "status": "draft", "id": "1c6107fe-3ced-566a-8ff5-b2dfe0d28425"}, {"name": "理（陈友谅次子）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "陈友谅次子，父死在武昌被张定边立帝，后降吴。", "biography": null, "status": "draft", "id": "95a1b1a7-8490-5130-923c-2219a20204f5"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "徐达率军北征", "description": "洪武3年（1370年）正月，徐达率军北征。", "start_year": 1370, "end_year": 1370, "time_original": "洪武3年（1370年）正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "077ba371-69f1-52fd-afee-756e56c13861"}, {"title": "明廷追封郭子兴为滁阳王", "description": "二月癸未，明廷追封已故的郭子兴为滁阳王。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e7a383fc-bcec-519a-8652-da5fe1b5a062"}, {"title": "明廷下诏访求可任六部的人才", "description": "二月戊子，明廷下诏访求能够到六部任职的人才。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3142c08f-b732-5730-ab6d-df80af7a0a19"}, {"title": "李文忠攻下兴和，擒获竹贞", "description": "二月，李文忠攻下兴和，进兵察罕脑儿，擒获元朝平章竹贞。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "375b866b-701c-583f-acdc-c9f428b38f0e"}, {"title": "明廷减免多地当年田租", "description": "三月庚寅，明廷下令免去南畿、河南、山东、北平、浙东和江西广信、饶州当年的田租。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0d810838-7f6e-5d89-9c8a-da9510c652fa"}, {"title": "朱元璋册封诸王", "description": "四月乙丑，朱元璋封九名皇子为王，另封从孙守谦为靖江王。原文列出各人的封号。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b2e0ac71-16d8-5fc0-9737-0107b73b2576"}, {"title": "徐达在沈儿峪击败扩廓帖木儿", "description": "四月，徐达在沈儿峪大败扩廓帖木儿，接受其部众投降。扩廓逃往和林。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a9887b0a-e827-5768-ab10-76330b44cc7a"}, {"title": "元帝在应昌去世，皇子继位", "description": "四月丙戌，元朝皇帝在应昌去世，其子爱猷识理达腊继位。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6bd7832f-172b-5a1e-a7ca-6690ec44499b"}, {"title": "明廷令地方长官荐举人才", "description": "五月丁酉，明廷下诏，要求地方长官荐举有学识、品行笃实的人士。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d1c472e7-818c-51ae-8d9a-31aaf9fbfa33"}, {"title": "明廷设置科举选拔人才", "description": "五月己亥，明廷设置科举选拔人才。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e4e33b89-24de-52e1-bcc6-780b657c0c02"}, {"title": "李文忠攻克应昌", "description": "五月甲辰，李文忠攻克应昌。元朝新君北走，其子买的里八剌被擒。《明史》记有五万多人归降。明军追至北庆州，未能赶上元朝新君，便撤回。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "10af71af-6d1e-5208-96fb-ba999606b56d"}, {"title": "邓愈攻克河州", "description": "五月，邓愈率军攻克河州。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a5690618-9905-57c7-9519-82b0cf49dda1"}, {"title": "明廷下诏供养无嗣开国将帅的家属", "description": "五月丁巳，明廷下诏，向没有后嗣的开国将帅之家发给俸禄。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bfdbde6a-3fc9-506e-983c-9ef58c24fca4"}, {"title": "朱元璋在山川坛祈雨", "description": "六月初一，朱元璋穿素服和草鞋步行到山川坛祈祷，在户外露宿三日，随后回到西庑斋戒。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2540b0fc-e78c-5858-8a29-4b3be4ec531f"}, {"title": "明廷为元朝旧主定谥号顺帝", "description": "六月壬申，李文忠的捷报送到。朱元璋命曾在元朝任官的人不用前来祝贺，并为去世的元朝皇帝定谥号顺帝。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9c714178-4267-5b5b-a833-fefb3a4ef4ba"}, {"title": "朱元璋拒绝为元朝皇子举行献俘礼", "description": "六月癸酉，被俘的元朝皇子买的里八剌送达京师。群臣请求行献俘礼，朱元璋不批准。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "96e2eb98-5f6b-5bd8-959a-ba7eb6089f3b"}, {"title": "明廷封买的里八剌为崇礼侯", "description": "六月乙亥，明廷封买的里八剌为崇礼侯。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f304cf96-0540-5d43-bb7c-cf0a0400e207"}, {"title": "明廷迁苏州等地无业百姓到临濠屯田", "description": "六月辛巳，明廷把苏州、松江、嘉兴、湖州、杭州没有生业的百姓迁到临濠耕种，提供资粮、耕牛和种子，免去三年赋役。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6120d0e-7c34-5d71-8f3f-3029ca24d1db"}, {"title": "傅友德击退进攻汉中的吴友仁", "description": "七月丙辰，明升的部将吴友仁进攻汉中，明朝参政傅友德率军将其击退。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3e0ac0c0-b5c5-59bc-af1a-78aa139d1eb1"}, {"title": "中书左丞杨宪被处死", "description": "七月，本纪记中书左丞杨宪获罪被处死。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6aa4cc6-fb29-526b-980c-1a422dd20ee5"}, {"title": "明廷派使者收葬中原遗骸", "description": "八月乙酉，明廷派使者收葬中原遗骸。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "86e3f11f-35e9-5657-b3fc-9c557f8d8520"}, {"title": "明廷命儒士为武官讲授经史", "description": "十月丙辰，明廷下诏，命儒士轮流在午门值班，给武官讲授经书和史书。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9719f49d-20c7-5a69-b437-8d6c0d3ba968"}, {"title": "周德兴奉命征讨覃垕", "description": "十月癸亥，周德兴任征南将军，出兵征讨覃垕。覃垕逃走。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7b5eaf55-1a59-5d2c-b54d-b9dd4e459874"}, {"title": "明朝北征军返回", "description": "十一月壬辰，明朝北征的军队返回。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8bbdb754-44d3-546b-81de-997aca3786f7"}, {"title": "李善长改封韩国公，并晋升为太师", "description": "洪武3年（1370年）十一月，李善长改封韩国公，并晋升为太师。", "start_year": 1370, "end_year": 1370, "time_original": "洪武3年（1370年）十一月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "2f7ffa23-5e10-57c1-ad16-17e0f80810b8"}, {"title": "徐达返回京城，改封魏国公，并晋升为太傅", "description": "洪武3年（1370年）十一月，徐达返回京城，改封魏国公，并晋升为太傅。", "start_year": 1370, "end_year": 1370, "time_original": "洪武3年（1370年）十一月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "aeb3596b-41ea-56e6-996e-4439586b36b3"}, {"title": "明廷下诏设置户籍和户帖", "description": "十一月辛亥，明廷命户部建立户籍和户帖，每年统计户口增减并上报，把这项制度列为法令。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "10be1696-2f93-5cd6-8bd9-9690d86e199b"}, {"title": "汪广洋获封忠勤伯", "description": "洪武3年（1370年）十一月，汪广洋获封忠勤伯。", "start_year": 1370, "end_year": 1370, "time_original": "洪武3年（1370年）十一月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "85c05d23-3049-532e-aa4f-d34e96c9e614"}, {"title": "刘基获封诚意伯", "description": "十一月乙卯，明廷封御史中丞刘基为诚意伯。", "start_year": 1370, "end_year": 1370, "time_original": "洪武三年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "28377200-b1d7-5a4a-8d5f-ad06cb844787"}, {"title": "明廷营建奉先殿", "description": "十二月甲子，明廷营建奉先殿。 按原历纪年，事情发生在公元1370至1371年之间。", "start_year": null, "end_year": null, "time_original": "洪武三年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b1329e68-9f73-5a0e-90b7-22ca0b3990cf"}, {"title": "明廷派使者祭祀和修葺历代帝王陵寝", "description": "十二月庚午，明廷派使者祭祀历代帝王的陵寝，并加以修葺。 按原历纪年，事情发生在公元1370至1371年之间。", "start_year": null, "end_year": null, "time_original": "洪武三年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c3875dad-cc4b-55b5-a05e-2fbdec87c8c5"}, {"title": "本纪记占城、爪哇和西洋入贡", "description": "本纪把占城、爪哇和所称的西洋入贡记在洪武三年，未详载各次年月。 按原历纪年，事情发生在公元1370至1371年之间。", "start_year": null, "end_year": null, "time_original": "洪武三年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1eed7a4d-8b79-5361-9a6b-66699e3d65be"}, {"title": "李善长退休", "description": "洪武4年（1371年）正月，李善长退休。", "start_year": 1371, "end_year": 1371, "time_original": "洪武4年（1371年）正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "0d85179d-7b72-507c-a9b3-ce5680e9846e"}, {"title": "汪广洋出任右丞相", "description": "洪武4年（1371年）正月，汪广洋出任右丞相。", "start_year": 1371, "end_year": 1371, "time_original": "洪武4年（1371年）正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "9eaaefe8-6b87-5546-977a-e66504c30463"}, {"title": "汤和、傅友德分路出兵攻蜀", "description": "正月丁亥，明廷命汤和率水军从瞿塘进攻蜀地，由周德兴、廖永忠辅助。同时派傅友德率步骑从秦、陇出兵，由顾时辅助。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e254ece3-323b-5410-b9e4-ba592f260182"}, {"title": "徐达出征北平", "description": "洪武4年（1371年）正月，徐达出征北平。", "start_year": 1371, "end_year": 1371, "time_original": "洪武4年（1371年）正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "9cf127ad-514d-5aad-a9a6-f2c973059bec"}, {"title": "明廷免除山西旱灾地区田租", "description": "正月戊申，明廷免除山西遭遇旱灾地区的田租。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "43a376c4-9a2e-5962-8100-d70aa362bb65"}, {"title": "元朝平章刘益献辽东归降", "description": "二月，元朝平章刘益献出辽东，向明廷归降。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "39190b50-7cc2-51ab-bb59-0e00a68bceb8"}, {"title": "明廷开始策试贡士", "description": "三月初一，明廷开始用策问考试各地贡士，吴伯宗等人分等获赐进士及第或出身。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "89a7a17e-72f3-5f91-ae5a-0e5ddbe93213"}, {"title": "诚意伯刘基退休", "description": "三月丁未，诚意伯刘基退休。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a0cd7971-0588-5695-888e-3f5cf9b573ce"}, {"title": "傅友德攻克阶州", "description": "四月丙戌，傅友德攻克阶州，文州、隆州、绵州随后相继被攻取。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "409e3542-3969-51a6-bcd4-d6c72ff7a975"}, {"title": "明廷免除江西、浙江秋粮", "description": "五月，明廷免除江西、浙江当年的秋粮。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dbd608f0-0904-5366-beab-82d01a085a1a"}, {"title": "傅友德攻克汉州", "description": "六月壬午，傅友德攻克汉州。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c9e26722-0d78-55df-bb46-f67abf80afb1"}, {"title": "廖永忠攻克夔州", "description": "六月辛卯，廖永忠攻克夔州。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0c553024-2d18-5c2e-b668-282408771578"}, {"title": "汤和到重庆，明升归降", "description": "六月癸卯，汤和率军到重庆，明升归降。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6923ad8b-be13-5735-898f-4c71360354c4"}, {"title": "傅友德攻下成都", "description": "七月辛酉，傅友德攻下成都，本纪记四川平定。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "06af58b4-0ebc-5d9a-b1ed-8e8eab72832f"}, {"title": "明升到京师，获封归义侯", "description": "七月乙丑，明升到达京师，明廷封他为归义侯。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3947ecca-5e18-5dbc-b650-52d7e5b7a649"}, {"title": "明廷减免中都等地田租", "description": "八月甲午，明廷免除中都、淮州、扬州、泰州、滁州和无为州的田租。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "55648feb-b31b-52b3-916d-e72ef37edce2"}, {"title": "明廷赈济陕西饥民", "description": "八月己酉，明廷下令赈济陕西遭受饥荒的百姓。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "877f291b-61fd-5a95-88bc-f6b9622f18ef"}, {"title": "洪武四年九月初一日食", "description": "九月初一，本纪记载发生日食。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b96f77e8-f70a-555c-9dbb-5ba4ee1d5a5a"}, {"title": "明朝征蜀军返回", "description": "十月丙申，明朝征蜀的军队返回。", "start_year": 1371, "end_year": 1371, "time_original": "洪武四年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "193f38ac-e2ef-5648-86c8-5b1ed8339fdf"}, {"title": "明廷下令严惩贪赃官吏", "description": "十一月庚申，明廷下令，官吏犯下贪赃之罪不得宽赦。 按原历纪年，事情发生在公元1371至1372年之间。", "start_year": null, "end_year": null, "time_original": "洪武四年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "480be6db-b6e9-5c43-a1d7-085436528a5f"}, {"title": "明廷免陕西、河南受灾地区田租", "description": "十一月，明廷免除陕西和河南遭灾地区的田租。 按原历纪年，事情发生在公元1371至1372年之间。", "start_year": null, "end_year": null, "time_original": "洪武四年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bad09830-1bb4-5066-9c62-a274d4d0cd09"}, {"title": "徐达返回京城", "description": "洪武4年（1371年）十二月，徐达返回京城。", "start_year": 1371, "end_year": 1371, "time_original": "洪武4年（1371年）十二月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "4e747866-3932-5eb9-8674-2c9937124f83"}, {"title": "本纪记安南等地入贡", "description": "洪武四年，史书记安南、浡泥、高丽、三佛齐、暹罗、日本和真腊都曾入贡，未逐次列出月份。 按原历纪年，事情发生在公元1371至1372年之间。", "start_year": null, "end_year": null, "time_original": "洪武四年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9bb9a643-8ef3-5cea-ab03-1525363ba4f1"}, {"title": "王祎奉诏出使云南", "description": "洪武五年正月癸丑，明廷派待制王祎出使云南，传诏给元朝梁王把匝剌瓦尔密。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a0ca2a06-8970-5341-b382-2969916909ab"}, {"title": "明廷迁陈理、明升到高丽", "description": "正月乙丑，明廷把陈理和明升迁到高丽。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9613a100-011e-534d-8f7f-f95eb34c0d4c"}, {"title": "明廷命徐达、李文忠、冯胜分路出兵", "description": "正月甲戌，明廷命徐达率兵经雁门前往和林，李文忠自应昌方向出兵，冯胜进取甘肃，征讨扩廓帖木儿。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "720c31ae-2500-5f41-8ca1-703f49d368a8"}, {"title": "明廷拒受陈叔明遣使进贡", "description": "二月丙戌，本纪记安南陈叔明杀死国主日熞，自立后派使者进贡，明廷拒绝接受。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6cfbd8eb-d3cf-597e-949e-c0dd57df8664"}, {"title": "蓝玉在土剌河击败扩廓帖木儿", "description": "三月丁卯，都督佥事蓝玉在土剌河击败扩廓帖木儿所部。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "02612d2c-8551-592c-9b9c-effb511d116c"}]'::jsonb)
